                    crate::testport::assert_eq_at(pfn_warn(f), ft_dec(rows, s6 + 1, s7), "warning bits", line);
                    crate::testport::assert_eq_at(pfn_vertical(f), ft_dec(rows, s7 + 1, s8), "vertical", line);
                    crate::testport::assert_eq_at(pfn_standard_font(f), ft_dec(rows, s8 + 1, e), "standard font", line);
