pub(crate) fn ft_cjk_code(rows: &[u8], from: i32, to: i32) -> i32 {
    // A code of a cjk.txt row: hex, or `d` and a signed decimal (a four-byte code).
    if crate::port::blob_u8(rows, from) == 100 {
        return ft_dec(rows, from + 1, to);
    }
    return ft_hex(rows, from, to);
}
