fn test_every_predefined_cmap_row_maps_as_its_file_says() {
    // Rows of cjk.txt: `cid /Name code cid` (the CID the Adobe CMap file gives the code, 0 for none) and
    // `uni Ordering cid code-point` (what cid2code.txt says), on every target.
    let rows: &[u8] = &crate::testport::test_file("fonts/cjk.txt")[..];
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let n: i32 = crate::port::blob_len(rows);
    let mut pos: i32 = 0;
    let mut line: i32 = 0;
    let mut count: i32 = 0;
    let mut e: i32 = 0;
    let mut s0: i32 = 0;
    let mut s1: i32 = 0;
    let mut s2: i32 = 0;
    let mut h: i32 = 0;
    let mut hit: i32 = 0;
    let mut coll: i32 = 0;
    while pos < n {
        line += 1;
        e = ft_nl(rows, pos);
        if (pos < e) && (crate::port::blob_u8(rows, pos) != 35) {
            count += 1;
            s0 = ft_tab(rows, pos, e);
            s1 = ft_tab(rows, s0 + 1, e);
            s2 = ft_tab(rows, s1 + 1, e);
            if crate::port::blob_u8(rows, pos) == 99 {
                pl_init(ar);
                pl_seek(ar, s0 + 1, s1);
                h = pl_parse(&crate::port::src_of_blob(rows), ar);
                hit = cjk_find_name(ar, h);
                crate::testport::assert_that_at(hit >= 0, "the CMap is one of the four collections'", line);
                crate::testport::assert_eq_at(cjk_cid(hit / 1000, hit % 1000, ft_cjk_code(rows, s1 + 1, s2)), ft_dec(rows, s2 + 1, e), "CID", line);
            }
            if crate::port::blob_u8(rows, pos) == 117 {
                coll = 0;
                if crate::port::blob_u8(rows, s0 + 1) == 71 {
                    coll = 1;
                }
                if crate::port::blob_u8(rows, s0 + 1) == 67 {
                    coll = 2;
                }
                if crate::port::blob_u8(rows, s0 + 1) == 75 {
                    coll = 3;
                }
                crate::testport::assert_eq_at(cjk_uni(coll, ft_dec(rows, s1 + 1, s2)), ft_hex(rows, s2 + 1, e), "Unicode of the CID", line);
            }
        }
        pos = e + 1;
    }
    crate::testport::assert_that(count > 5000, "the CJK rows were read");
}
pub(crate) fn ft_push_zeros(mut g: &mut crate::port::Cells, k: i32) -> i32 {
    let mut i: i32 = 0;
    while i < k {
        crate::port::cells_push(g, 0);
        i += 1;
    }
    return 0;
}
pub(crate) fn ft_cut_program(prog: &[u8], mut g: &mut crate::port::Cells) -> i32 {
    // `fp-simple` on every prefix of the program: answers how many prefixes were tried.
    let n: i32 = crate::port::blob_len(prog);
    let mut cut: i32 = 0;
    let mut tries: i32 = 0;
    while cut <= n {
        let piece: &mut crate::port::Cells = &mut crate::port::Cells::new();
        let mut j: i32 = 0;
        while j < cut {
            crate::port::cells_push(piece, crate::port::blob_u8(prog, j));
            j += 1;
        }
        fp_simple(g, 16, 32, &crate::testport::cells_blob(piece)[..], 0);
        fp_simple(g, 16, 32, &crate::testport::cells_blob(piece)[..], 1);
        tries += 1;
        cut += 1;
    }
    return tries;
}
#[test]
fn test_a_font_program_cut_at_every_byte_never_faults() {
    // Type 1, CFF, TrueType and OpenType programs, every prefix of each: no read past an end, no loop.
    let g: &mut crate::port::Cells = &mut crate::port::Cells::new();
    ft_push_zeros(g, 1700);
    let tries: i32 = (ft_cut_program(&crate::testport::test_file("fonts/prog-t1.bin")[..], g) + ft_cut_program(&crate::testport::test_file("fonts/prog-cff.bin")[..], g)) + (ft_cut_program(&crate::testport::test_file("fonts/prog-tt.bin")[..], g) + ft_cut_program(&crate::testport::test_file("fonts/prog-otf.bin")[..], g));
    crate::testport::assert_that(tries > 1000, "the prefixes were tried");
}
pub(crate) fn ft_name_bytes_row(rows: &[u8], from: i32, to: i32, mut g: &mut crate::port::Cells, kind: i32, mut t: &mut String) -> i32 {
    // `fp-name-cps` on the name bytes rows[from+1, to) (the slash skipped): the code points, `-` none.
    let cnt: i32 = fp_name_cps(g, 16, rows, from + 1, to, kind / 122);
    let mut i: i32 = 0;
    if cnt == 0 {
        crate::port::text_cp(t, 45);
        return 0;
    }
    while i < cnt {
        if i > 0 {
            crate::port::text_cp(t, 43);
        }
        ft_emit_hex(t, crate::port::cells_at(g, 17 + i));
        i += 1;
    }
    return 0;
}
