pub(crate) fn ft_mix(acc: i32, v: i32) -> i32 {
    // A small order-sensitive digest, wrapping inside 2^24 so it cannot overflow.
    return (((acc % 8388593) * 31) + ((v % 8388593) + 7)) % 16777213;
}
pub(crate) fn ft_digest_font(pdf: &crate::port::Src, num: i32) -> i32 {
    // Open the file, load font object `num`, and digest its status, warnings, metrics and the answer for
    // each of 512 codes; -1 when the source missed (nothing of the attempt may be kept, D075).
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let dc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let b: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ostatus: i32 = pd_open(pdf, ar, dc, a, b, st);
    let mut acc: i32 = ostatus;
    let mut h: i32 = 0;
    let mut status: i32 = 0;
    let mut code: i32 = 0;
    let mut cnt: i32 = 0;
    let mut i: i32 = 0;
    if ps_missed(pdf) {
        return -1;
    }
    h = pd_get(pdf, ar, dc, a, b, st, num);
    status = pfn_load(pdf, ar, dc, a, b, st, f, out, h);
    if ps_missed(pdf) {
        return -1;
    }
    acc = ft_mix(acc, status);
    acc = ft_mix(acc, pfn_warn(f));
    acc = ft_mix(acc, pfn_kind_of(f));
    acc = ft_mix(acc, pfn_ascent(f));
    while code < 512 {
        cnt = pfn_map(f, code);
        acc = ft_mix(acc, cnt);
        i = 0;
        while i < cnt {
            acc = ft_mix(acc, pfn_cp(f, i));
            i += 1;
        }
        acc = ft_mix(acc, pfn_how_of(f));
        acc = ft_mix(acc, pfn_width(f, code));
        acc = ft_mix(acc, pfn_cid(f, code));
        code += 1;
    }
    return acc;
}
pub(crate) fn ft_digest_async(bytes: &[u8], num: i32, chunk: i32) -> i32 {
    // `ft-digest-font` through a source of `chunk`-byte chunks, re-run on a fresh view until an attempt
    // does not miss; -2 after 60 rounds.
    let base: &crate::port::Src = &crate::testport::src_chunked(bytes, chunk, 0);
    let mut round: i32 = 0;
    let mut more: i32 = 1;
    let mut d: i32 = 0;
    while more == 1 {
        let v: &crate::port::Src = &crate::testport::src_view(base);
        d = ft_digest_font(v, num);
        if d == -1 {
            crate::testport::src_ctl(base, 0, round);
            round += 1;
            if round > 60 {
                more = 0;
                d = -2;
            }
        } else {
            more = 0;
        }
    }
    return d;
}
pub(crate) fn ft_async_fonts(chunk: i32) -> i32 {
    // Every font of progs.txt through an async source: the number whose digest is not the memory one.
    let rows: &[u8] = &crate::testport::test_file("fonts/progs.txt")[..];
    let pdf: &[u8] = &crate::testport::test_file("fonts/progs.pdf")[..];
    let n: i32 = crate::port::blob_len(rows);
    let mut pos: i32 = 0;
    let mut e: i32 = 0;
    let mut s0: i32 = 0;
    let mut s1: i32 = 0;
    let mut s2: i32 = 0;
    let mut num: i32 = 0;
    let mut fonts: i32 = 0;
    let mut bad: i32 = 0;
    let mut want: i32 = 0;
    let mut got: i32 = 0;
    while pos < n {
        e = ft_nl(rows, pos);
        if (pos < e) && (crate::port::blob_u8(rows, pos) == 102) {
            s0 = ft_tab(rows, pos, e);
            s1 = ft_tab(rows, s0 + 1, e);
            s2 = ft_tab(rows, s1 + 1, e);
            num = ft_dec(rows, s1 + 1, s2);
            fonts += 1;
            want = ft_digest_font(&crate::port::src_of_blob(pdf), num);
            got = ft_digest_async(pdf, num, chunk);
            if (want < 0) || (want != got) {
                bad += 1;
            }
        }
        pos = e + 1;
    }
    if fonts < 25 {
        return -1;
    }
    return bad;
}
#[test]
fn test_every_program_font_is_the_same_through_an_async_source_of_64_byte_chunks() {
    crate::testport::assert_eq(ft_async_fonts(64), 0, "every font of progs.pdf through 64-byte chunks");
}
#[test]
fn test_every_program_font_is_the_same_through_an_async_source_of_512_byte_chunks() {
    crate::testport::assert_eq(ft_async_fonts(512), 0, "every font of progs.pdf through 512-byte chunks");
}
#[test]
fn test_document_cache_restores_exact_font_cells_after_eviction() {
    let src: &crate::port::Src = &crate::port::src_of_blob(&crate::testport::test_file("fonts/fonts.pdf")[..]);
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let dc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let b: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cx: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ox: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let loaded: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cached: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut object: i32 = 1;
    let mut fh: i32 = 0;
    let mut j: i32 = 0;
    let mut before: i32 = 0;
    let mut charge: i32 = 0;
    crate::testport::assert_eq(pd_open(src, ar, dc, a, b, st), 0, "font fixture opens");
    pc_init(cx, ox);
    while object <= 8 {
        fh = pd_get(src, ar, dc, a, b, st, object);
        crate::testport::assert_eq(pc_f_cached(src, ar, dc, a, b, st, cx, cached, out, object, fh), 0, "fill more than four slots");
        object += 1;
        if (object == 3) || (object == 5) {
            object += 1;
        }
    }
    object = 1;
    while object <= 8 {
        fh = pd_get(src, ar, dc, a, b, st, object);
        before = pd_total_used(dc);
        crate::testport::assert_eq(pfn_load(src, ar, dc, a, b, st, loaded, out, fh), 0, "fresh reference load");
        charge = pd_total_used(dc) - before;
        crate::port::cells_drop(cached, 0);
        before = pd_total_used(dc);
        crate::testport::assert_eq(pc_f_cached(src, ar, dc, a, b, st, cx, cached, out, object, fh), 0, "reload after slot eviction");
        crate::testport::assert_eq(pd_total_used(dc) - before, charge, "cached loads charge the same decoded-byte budget");
        crate::testport::assert_eq(crate::port::cells_len(cached), crate::port::cells_len(loaded), "same parsed size");
        j = 0;
        while j < crate::port::cells_len(loaded) {
            crate::testport::assert_eq(crate::port::cells_at(cached, j), crate::port::cells_at(loaded, j), "every parsed cell is identical");
            j += 1;
        }
        crate::testport::assert_eq(pfn_map(cached, 65), pfn_map(loaded, 65), "same mapping after restoration");
        crate::testport::assert_eq(pfn_width(cached, 65), pfn_width(loaded, 65), "same width after restoration");
        object += 1;
        if (object == 3) || (object == 5) {
            object += 1;
        }
    }
}
